<?php
require __DIR__.'/../includes/bootstrap.php';
$id=trim((string)($_GET['id']??''));
if(!isset($_GET['modal'])){header('Location: /agri-fishery/market.php');exit;}
$item=null;foreach(portal_items() as $candidate)if((string)$candidate['id']===$id&&$candidate['pillar']==='Agri-Fishery'){$item=$candidate;break;}
if(!$item){http_response_code(404);echo '<div class="product-modal-error"><i class="fa-regular fa-circle-xmark"></i><strong>Product unavailable</strong><span>This listing may have been removed or archived.</span></div>';exit;}
$seller=['name'=>$item['provider'],'location'=>$item['location'],'email'=>''];try{$pdo=database();if($pdo){$q=$pdo->prepare("SELECT p.name,p.location,u.email FROM listings l LEFT JOIN providers p ON p.id=l.provider_id LEFT JOIN users u ON u.id=p.owner_user_id WHERE l.id=:id");$q->execute(['id'=>$id]);$row=$q->fetch();if($row){$seller['name']=$row['name']?:$item['provider'];$seller['location']=$row['location']?:$item['location'];$seller['email']=$row['email']??'';}}}catch(Throwable $ignored){}
?>
<div class="product-modal-layout"><div class="product-modal-art"><?php if(!empty($item['image_url'])): ?><img src="<?= h($item['image_url']) ?>" alt="<?= h($item['title']) ?>"><?php else: ?><span><?= h($item['image']??'') ?></span><?php endif; ?><small><?= h($item['tag']) ?></small></div><div class="product-modal-details"><div class="eyebrow">FRESH FROM A LOCAL SELLER</div><h2><?= h($item['title']) ?></h2><div class="product-detail-location"><i class="fa-solid fa-location-dot"></i> <?= h($item['location']) ?></div><div class="product-detail-price"><?= money((float)$item['price']) ?><small><?= h($item['unit']) ?></small></div><p><?= h($item['description']) ?></p><div class="product-detail-note"><i class="fa-solid fa-circle-info"></i> Confirm harvest availability, quantity, pickup or delivery with the seller.</div><form class="product-add-form" method="post" action="/agri-fishery/market.php"><input type="hidden" name="action" value="add_product"><input type="hidden" name="item_id" value="<?= h((string)$item['id']) ?>"><label>Quantity<input type="number" name="quantity" value="1" min="1" max="20"></label><button class="btn btn-darkgreen" type="submit"><i class="fa-solid fa-basket-shopping"></i> Add to basket</button></form><div class="product-modal-actions"><form method="post" action="/agri-fishery/market.php"><input type="hidden" name="action" value="save_product"><input type="hidden" name="item_id" value="<?= h((string)$item['id']) ?>"><button class="btn btn-outline-green" type="submit"><i class="fa-regular fa-heart"></i> Save item</button></form><details class="product-review-form"><summary>Write a review</summary><form method="post" action="/agri-fishery/market.php"><input type="hidden" name="action" value="submit_review"><input type="hidden" name="item_id" value="<?= h((string)$item['id']) ?>"><label>Rating<select name="rating"><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Okay</option><option value="2">2 - Poor</option><option value="1">1 - Not recommended</option></select></label><label>Review<textarea name="comment" rows="2" required></textarea></label><button class="btn btn-darkgreen" type="submit">Submit review</button></form></details></div></div><aside class="seller-detail-card"><div class="seller-detail-icon"><i class="fa-solid fa-store"></i></div><div class="eyebrow">SELLER INFORMATION</div><h3><?= h($seller['name']) ?></h3><p><i class="fa-solid fa-location-dot"></i> <?= h($seller['location']) ?></p><?php if($seller['email']!==''): ?><a class="seller-contact-link" href="mailto:<?= h($seller['email']) ?>"><i class="fa-regular fa-envelope"></i> Contact seller</a><?php else: ?><span class="seller-contact-link"><i class="fa-solid fa-user-check"></i> Community seller</span><?php endif; ?><small>Confirm product details and availability before purchase.</small></aside></div>
